param(
    [ValidateSet('Now', 'Start', 'Note', 'Verdict', 'Complete', 'History', 'Detail')]
    [Parameter(Mandatory)][string]$Mode,
    [string]$VerdictPath = '[HOME]/github/WordGame/.mcpServer/wordpairs/docs/receipts/hv/20261029T094325-admin-pwa-source-round5.verdict.json',
    [string]$NotePath = ''
)

