$repl = '[HOME]/github/mcpserver-claude-code-plugin/lib/repl-invoke.ps1'
$workDir = Join-Path $PSScriptRoot 'session-params'
if (-not (Test-Path -LiteralPath $workDir)) { $null = New-Item -ItemType Directory -Path $workDir }
$requestId = 'req-20261029T144333Z-prompt-73ea'
$sessionId = 'ClaudeCode-20261029T144329Z-plugin-session'
Set-Location -LiteralPath '[HOME]/github/WordGame/.mcpServer/wordpairs'

function Invoke-Repl {
    param([Parameter(Mandatory)][string]$Method, [Parameter(Mandatory)][System.Collections.IDictionary]$Params, [Parameter(Mandatory)][string]$Name)
