    ConvertTo-Yaml $Params | Set-Content -LiteralPath $path -Encoding utf8
    $output = & pwsh -NoProfile -NonInteractive -File $repl -Method $Method -ParamsPath $path 2>&1
    $exit = $LASTEXITCODE
    $outPath = Join-Path $workDir ($Name + '.out.txt')
    $output | Set-Content -LiteralPath $outPath -Encoding utf8
    [pscustomobject]@{ name = $Name; method = $Method; exitCode = $exit; outLines = @($output).Count; tail = (@($output) | Select-Object -Last 3) -join ' | ' } | ConvertTo-Json -Compress
}

function Split-Text {
    param([string]$Text, [int]$Size = 6000)
    $parts = [System.Collections.Generic.List[string]]::new()
    for ($i = 0; $i -lt $Text.Length; $i += $Size) { $parts.Add($Text.Substring($i, [Math]::Min($Size, $Text.Length - $i))) }
    return , $parts.ToArray()
}

$utc = [DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ')
