            tags           = @('hostile-validation', 'admin-pwa-source-round5', '6071b2d', 'parent:Codex-20261027T100516Z-plugin-session', 'parentRequest:req-20261029T135928Z-prompt-c0e1', 'earlierRetry:req-20261029T042903Z-prompt-c233', 'FR-LOBBYDISCOVERY-019', 'TEST-ROOMINVITATIONS-025', 'TR-SCHEMA-PROVISIONING-023', 'TEST-SCHEMAPROVISIONING-123')
        }
        Invoke-Repl -Method 'workflow.sessionlog.updateTurn' -Params $params -Name 'start-update'
        $dialog = [ordered]@{
            requestId   = $requestId
            dialogItems = @(
                [ordered]@{ timestamp = $utc; role = 'model'; category = 'observation'; content = 'Linkage: this reviewer turn is ' + $sessionId + ' / ' + $requestId + ' (hook-opened, persisted true in plugin cache). Parent: Codex-20261027T100516Z-plugin-session / req-20261029T135928Z-prompt-c0e1. Earlier retry turn: req-20261029T042903Z-prompt-c233. add-profile ran first (1 profile file, PROFILE-MERGED.md, 376 lines); full marker (398 lines) and AGENTS.md (14 lines) read; credentials not echoed. Reviewer conduct note: my first Bash call (a plain directory listing) was denied by the launch allowlist; I first reported Bash as fully denied, then corrected that after reading the request launchCommand, which permits pwsh -NoProfile -NonInteractive -File.' }
            )
        }
        Invoke-Repl -Method 'workflow.sessionlog.appendDialog' -Params $dialog -Name 'start-dialog'
