        Invoke-Repl -Method 'workflow.sessionlog.appendDialog' -Params ([ordered]@{ requestId = $requestId; dialogItems = @([ordered]@{ timestamp = $utc; role = 'model'; category = 'observation'; content = $text }) }) -Name ('note-' + $stamp)
    }
    'Verdict' {
        $verdict = Get-Content -LiteralPath $VerdictPath -Raw | ConvertFrom-Json -AsHashtable
        $items = [System.Collections.Generic.List[object]]::new()
        $prose = [string]$verdict['verdictProse']
        $n = 0
        foreach ($part in (Split-Text -Text $prose)) { $n++; $items.Add([ordered]@{ timestamp = $utc; role = 'model'; category = 'decision'; content = "VERDICT PROSE part $n`n" + $part }) }
