        }
        foreach ($f in $verdict['findings']) {
            $items.Add([ordered]@{ timestamp = $utc; role = 'model'; category = 'decision'; content = ($f | ConvertTo-Json -Depth 6 -Compress) })
        }
        $json = Get-Content -LiteralPath $VerdictPath -Raw
        $n = 0
        foreach ($part in (Split-Text -Text $json)) { $n++; $items.Add([ordered]@{ timestamp = $utc; role = 'model'; category = 'tool_result'; content = "VERDICT JSON part $n (file $VerdictPath)`n" + $part }) }
