#Requires -Version 7.0
[CmdletBinding()]
param()

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

Import-Module powershell-yaml -ErrorAction Stop
$markerPath = '[HOME]/github/WordGame/.mcpServer/wordpairs/AGENTS-README-FIRST.yaml'
$marker = Get-Content -LiteralPath $markerPath -Raw | ConvertFrom-Yaml

function Get-MarkerValue {
    param([Parameter(Mandatory)][string]$Field)
    switch ($Field) {
        'canonicalization' { return [string]$marker['signature']['canonicalization'] }
        'agentPlugins.policy' { return [string]$marker['agent_plugins']['policy'] }
        'agentPlugins.contractDigest' { return [string]$marker['agent_plugins']['contract_digest'] }
    }
    if ($Field.StartsWith('endpoints.')) { return [string]$marker['endpoints'][$Field.Substring(10)] }
    $value = $marker[$Field]
    if ($value -is [DateTime]) { return $value.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss.fffffff') + '+00:00' }
    return [string]$value
}

$builder = [System.Text.StringBuilder]::new()
foreach ($field in $marker['signature']['fields']) {
    [void]$builder.Append($field).Append('=').Append((Get-MarkerValue -Field $field)).Append("`n")
}
$key = [System.Text.Encoding]::UTF8.GetBytes([string]$marker['apiKey'])
$hmac = [System.Security.Cryptography.HMACSHA256]::new($key)
$computed = [Convert]::ToHexString($hmac.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($builder.ToString())))
$expected = [string]$marker['signature']['value']

$nonce = [Guid]::NewGuid().ToString('N')
$healthUri = [string]$marker['baseUrl'] + [string]$marker['endpoints']['health'] + '?nonce=' + $nonce
$healthBody = ''
$healthOk = $false
try {
    $response = Invoke-WebRequest -Uri $healthUri -Method Get -TimeoutSec 30
    $healthBody = [string]$response.Content
    $healthOk = $healthBody.Contains($nonce)
} catch {
    $healthBody = 'ERROR ' + $_.Exception.Message
}

[pscustomobject]@{
    checkedAt          = (Get-Date -Format s)
    signatureMatch     = ($computed -eq $expected)
    signatureExpected8 = $expected.Substring(0, 8)
    signatureComputed8 = $computed.Substring(0, 8)
    nonceEchoed        = $healthOk
    healthBodyLength   = $healthBody.Length
    workspacePath      = [string]$marker['workspacePath']
} | ConvertTo-Json -Compress

