#Requires -Version 7.0
[CmdletBinding()]
param(
    [ValidateSet('Now', 'Start', 'Note', 'Verdict', 'Complete', 'History', 'Detail')]
    [Parameter(Mandatory)][string]$Mode,
    [string]$VerdictPath = '',
    [string]$NotePath = ''
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

Import-Module powershell-yaml -ErrorAction Stop
$repl = '[HOME]/github/mcpserver-claude-code-plugin/lib/repl-invoke.ps1'
$workDir = Join-Path $PSScriptRoot 'session-params'
if (-not (Test-Path -LiteralPath $workDir)) { $null = New-Item -ItemType Directory -Path $workDir }
$requestId = 'req-20261029T152519Z-prompt-94ed'
$sessionId = 'ClaudeCode-20261029T152513Z-plugin-session'
Set-Location -LiteralPath '[HOME]/github/WordGame/.mcpServer/wordpairs'

function Invoke-Repl {
    param([Parameter(Mandatory)][string]$Method, [Parameter(Mandatory)][System.Collections.IDictionary]$Params, [Parameter(Mandatory)][string]$Name)
    $path = Join-Path $workDir ($Name + '.yaml')
    ConvertTo-Yaml $Params | Set-Content -LiteralPath $path -Encoding utf8
    $output = & pwsh -NoProfile -NonInteractive -File $repl -Method $Method -ParamsPath $path 2>&1
    $exit = $LASTEXITCODE
    $outPath = Join-Path $workDir ($Name + '.out.txt')
    $output | Set-Content -LiteralPath $outPath -Encoding utf8
    [pscustomobject]@{ name = $Name; method = $Method; exitCode = $exit; outLines = @($output).Count; tail = (@($output) | Select-Object -Last 3) -join ' | ' } | ConvertTo-Json -Compress
}

function Split-Text {
    param([string]$Text, [int]$Size = 6000)
    $parts = [System.Collections.Generic.List[string]]::new()
    for ($i = 0; $i -lt $Text.Length; $i += $Size) { $parts.Add($Text.Substring($i, [Math]::Min($Size, $Text.Length - $i))) }
    return , $parts.ToArray()
}

$utc = [DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ')
$stamp = Get-Date -Format 'yyyyMMddTHHmmss'
switch ($Mode) {
    'Now' { 'LOCAL=' + (Get-Date -Format s) + ' UTC=' + $utc }
    'Start' {
        'LOCAL=' + (Get-Date -Format s)
        $params = [ordered]@{
            requestId      = $requestId
            queryTitle     = 'HV round6: Claude Opus staging-readiness review of wordpairs 3fb4a49'
            interpretation = 'Independent hostile validation (read-only) of source revision 3fb4a49a28ce5281ab91fa88c4d488458762ea27 for staging readiness. Parent Codex-20261027T100516Z-plugin-session / req-20261029T135928Z-prompt-c0e1; earlier retry turn req-20261029T042903Z-prompt-c233. Request receipt docs/receipts/hv/20261029T102510-admin-pwa-source-round6.request.jsonl. No product, requirement, TODO or Git mutations; no subagents; no builds or test runs.'
            tags           = @('hostile-validation', 'admin-pwa-source-round6', '3fb4a49', 'parent:Codex-20261027T100516Z-plugin-session', 'parentRequest:req-20261029T135928Z-prompt-c0e1', 'earlierRetry:req-20261029T042903Z-prompt-c233', 'FR-LOBBYDISCOVERY-019', 'TEST-ROOMINVITATIONS-025', 'TR-SCHEMA-PROVISIONING-023', 'TEST-SCHEMAPROVISIONING-123')
        }
        Invoke-Repl -Method 'workflow.sessionlog.updateTurn' -Params $params -Name 'start-update'
        $dialog = [ordered]@{
            requestId   = $requestId
            dialogItems = @(
                [ordered]@{ timestamp = $utc; role = 'model'; category = 'observation'; content = 'Linkage: this reviewer turn is ' + $sessionId + ' / ' + $requestId + ' (hook-opened; plugin cache persisted true). Parent: Codex-20261027T100516Z-plugin-session / req-20261029T135928Z-prompt-c0e1. Earlier retry turn: req-20261029T042903Z-prompt-c233. add-profile ran first (1 profile file, PROFILE-MERGED.md, 376 lines read in full); full marker (398 lines) and AGENTS.md (14 lines) read; credentials not echoed. Reviewer conduct: my first Bash call (a plain listing plus date) was denied by the launch allowlist; I told the operator Bash was fully denied, then corrected that after reading the request launchCommand, which permits pwsh -NoProfile -NonInteractive -File.' }
            )
        }
        Invoke-Repl -Method 'workflow.sessionlog.appendDialog' -Params $dialog -Name 'start-dialog'
    }
    'Note' {
        $text = Get-Content -LiteralPath $NotePath -Raw
        Invoke-Repl -Method 'workflow.sessionlog.appendDialog' -Params ([ordered]@{ requestId = $requestId; dialogItems = @([ordered]@{ timestamp = $utc; role = 'model'; category = 'observation'; content = $text }) }) -Name ('note-' + $stamp)
    }
    'Verdict' {
        $verdict = Get-Content -LiteralPath $VerdictPath -Raw | ConvertFrom-Json -AsHashtable
        $items = [System.Collections.Generic.List[object]]::new()
        $prose = [string]$verdict['verdictProse']
        $n = 0
        foreach ($part in (Split-Text -Text $prose)) { $n++; $items.Add([ordered]@{ timestamp = $utc; role = 'model'; category = 'decision'; content = "VERDICT PROSE part $n`n" + $part }) }
        foreach ($it in $verdict['items']) {
            $items.Add([ordered]@{ timestamp = $utc; role = 'model'; category = 'observation'; content = ('{0} [{1}] {2}: {3} | anchors: {4} | finding: {5}' -f $it['id'], $it['surface'], $it['status'], $it['claim'], (@($it['anchors']) -join '; '), $it['finding']) })
        }
        foreach ($f in $verdict['findings']) {
            $items.Add([ordered]@{ timestamp = $utc; role = 'model'; category = 'decision'; content = ($f | ConvertTo-Json -Depth 6 -Compress) })
        }
        $json = Get-Content -LiteralPath $VerdictPath -Raw
        $n = 0
        foreach ($part in (Split-Text -Text $json)) { $n++; $items.Add([ordered]@{ timestamp = $utc; role = 'model'; category = 'tool_result'; content = "VERDICT JSON part $n (file $VerdictPath)`n" + $part }) }
        $batch = 0
        for ($i = 0; $i -lt $items.Count; $i += 12) {
            $batch++
            $slice = @($items[$i..([Math]::Min($i + 11, $items.Count - 1))])
            Invoke-Repl -Method 'workflow.sessionlog.appendDialog' -Params ([ordered]@{ requestId = $requestId; dialogItems = $slice }) -Name ('verdict-dialog-{0:D2}' -f $batch)
        }
        'DIALOG-ITEMS=' + $items.Count + ' BATCHES=' + $batch
        $actions = [System.Collections.Generic.List[object]]::new()
        $order = 0
        foreach ($d in $verdict['designDecisions']) { $order++; $actions.Add([ordered]@{ order = $order; description = [string]$d; type = 'design_decision'; status = 'completed'; filePath = '' }) }
        $order++; $actions.Add([ordered]@{ order = $order; description = 'Wrote complete verdict JSON (built from PowerShell objects).'; type = 'create'; status = 'completed'; filePath = $VerdictPath })
        $order++; $actions.Add([ordered]@{ order = $order; description = 'Read-only review tools (parser and PSScriptAnalyzer clean before each run) and QBrain readbacks; git-ignored by .gitignore:22.'; type = 'create'; status = 'completed'; filePath = 'docs/receipts/hv/claude-opus-round6-tools/' })
        Invoke-Repl -Method 'workflow.sessionlog.appendActions' -Params ([ordered]@{ requestId = $requestId; actions = $actions.ToArray() }) -Name 'verdict-actions'
        Invoke-Repl -Method 'workflow.sessionlog.updateTurn' -Params ([ordered]@{ requestId = $requestId; response = $prose }) -Name 'verdict-update'
    }
    'Complete' {
        $verdict = Get-Content -LiteralPath $VerdictPath -Raw | ConvertFrom-Json -AsHashtable
        Invoke-Repl -Method 'workflow.sessionlog.completeTurn' -Params ([ordered]@{ requestId = $requestId; response = [string]$verdict['verdictProse'] }) -Name 'complete'
    }
    'History' {
        Invoke-Repl -Method 'workflow.sessionlog.queryHistory' -Params ([ordered]@{ agent = 'ClaudeCode'; limit = 5; offset = 0 }) -Name ('history-' + $stamp)
    }
    'Detail' {
        $path = Join-Path $workDir ("turn-detail-$stamp.yaml")
        ConvertTo-Yaml ([ordered]@{ agent = 'ClaudeCode'; limit = 10 }) | Set-Content -LiteralPath $path -Encoding utf8
        $output = & pwsh -NoProfile -NonInteractive -File $repl -Method 'client.SessionLog.QueryAsync' -ParamsPath $path 2>&1
        $exit = $LASTEXITCODE
        $outPath = Join-Path $workDir ("turn-detail-$stamp.out.txt")
        $output | Set-Content -LiteralPath $outPath -Encoding utf8
        $docs = @(($output | Out-String) -split "(?m)^---\s*$" | Where-Object { $_.Trim() })
        $doc = ConvertFrom-Yaml $docs[0]
        $result = $doc['payload']['result']
        $sessionItems = if ($result -is [System.Collections.IDictionary] -and $result.Contains('items')) { $result['items'] } else { $result }
        $found = $null
        foreach ($s in @($sessionItems)) {
            if ([string]$s['sessionId'] -ne $sessionId) { continue }
            foreach ($t in @($s['turns'])) { if ([string]$t['requestId'] -eq $requestId) { $found = $t } }
        }
        if (-not $found) {
            [pscustomobject]@{ exitCode = $exit; found = $false; outPath = $outPath; readAt = (Get-Date -Format s) } | ConvertTo-Json -Compress
            return
        }
        $dialog = @($found['processingDialog'])
        $texts = @($dialog | ForEach-Object { [string]$_['content'] })
        $joined = $texts -join "`n"
        $actions = if ($found.Contains('actions')) { @($found['actions']) } else { @() }
        $expect = ''
        if ($VerdictPath -and (Test-Path -LiteralPath $VerdictPath)) {
            $v = Get-Content -LiteralPath $VerdictPath -Raw | ConvertFrom-Json -AsHashtable
            $expect = 'OverallVerdict {0}. Accuracy {1}. Completeness {2}.' -f $v['OverallVerdict'], $v['accuracy'], $v['completeness']
        }
        [pscustomobject]@{
            exitCode              = $exit
            found                 = $true
            sessionId             = $sessionId
            requestId             = $requestId
            status                = [string]$found['status']
            queryTitle            = [string]$found['queryTitle']
            dialogItems           = $dialog.Count
            actions               = $actions.Count
            designDecisionActions = @($actions | Where-Object { [string]$_['type'] -eq 'design_decision' }).Count
            proseParts            = ([regex]::Matches($joined, 'VERDICT PROSE part')).Count
            jsonParts             = ([regex]::Matches($joined, 'VERDICT JSON part')).Count
            itemLines             = @($texts | Where-Object { $_ -match '^S[1-4]-\d\d \[' }).Count
            findingObjects        = @($texts | Where-Object { $_ -match '^\{"id":"(F|I)-R6-' }).Count
            responseHasVerdict    = if ($expect) { ([string]$found['response']).Contains($expect) } else { $false }
            outPath               = $outPath
            readAt                = (Get-Date -Format s)
        } | ConvertTo-Json -Compress
    }
}

