        foreach ($d in $verdict['designDecisions']) { $order++; $actions.Add([ordered]@{ order = $order; description = [string]$d; type = 'design_decision'; status = 'completed'; filePath = '' }) }
        $order++; $actions.Add([ordered]@{ order = $order; description = 'Wrote complete verdict JSON (built from PowerShell objects).'; type = 'create'; status = 'completed'; filePath = $VerdictPath })
        $order++; $actions.Add([ordered]@{ order = $order; description = 'Read-only review tools (parser and PSScriptAnalyzer clean before each run) and QBrain readbacks; git-ignored by .gitignore:22.'; type = 'create'; status = 'completed'; filePath = 'docs/receipts/hv/claude-opus-round6-tools/' })
        Invoke-Repl -Method 'workflow.sessionlog.appendActions' -Params ([ordered]@{ requestId = $requestId; actions = $actions.ToArray() }) -Name 'verdict-actions'
        Invoke-Repl -Method 'workflow.sessionlog.updateTurn' -Params ([ordered]@{ requestId = $requestId; response = $prose }) -Name 'verdict-update'
    }
    'Complete' {
        $verdict = Get-Content -LiteralPath $VerdictPath -Raw | ConvertFrom-Json -AsHashtable
        Invoke-Repl -Method 'workflow.sessionlog.completeTurn' -Params ([ordered]@{ requestId = $requestId; response = [string]$verdict['verdictProse'] }) -Name 'complete'
    }
    'History' {
        Invoke-Repl -Method 'workflow.sessionlog.queryHistory' -Params ([ordered]@{ agent = 'ClaudeCode'; limit = 5; offset = 0 }) -Name ('history-' + $stamp)
    }
    'Detail' {
        $path = Join-Path $workDir ("turn-detail-$stamp.yaml")
        ConvertTo-Yaml ([ordered]@{ agent = 'ClaudeCode'; limit = 10 }) | Set-Content -LiteralPath $path -Encoding utf8
        $output = & pwsh -NoProfile -NonInteractive -File $repl -Method 'client.SessionLog.QueryAsync' -ParamsPath $path 2>&1
        $exit = $LASTEXITCODE
        $outPath = Join-Path $workDir ("turn-detail-$stamp.out.txt")
        $output | Set-Content -LiteralPath $outPath -Encoding utf8
        $docs = @(($output | Out-String) -split "(?m)^---\s*$" | Where-Object { $_.Trim() })
        $doc = ConvertFrom-Yaml $docs[0]
        $result = $doc['payload']['result']
        $sessionItems = if ($result -is [System.Collections.IDictionary] -and $result.Contains('items')) { $result['items'] } else { $result }
        $found = $null
        foreach ($s in @($sessionItems)) {
            if ([string]$s['sessionId'] -ne $sessionId) { continue }
            foreach ($t in @($s['turns'])) { if ([string]$t['requestId'] -eq $requestId) { $found = $t } }
        }
        if (-not $found) {
            [pscustomobject]@{ exitCode = $exit; found = $false; outPath = $outPath; readAt = (Get-Date -Format s) } | ConvertTo-Json -Compress
            return
        }
        $dialog = @($found['processingDialog'])
        $texts = @($dialog | ForEach-Object { [string]$_['content'] })
        $joined = $texts -join "`n"
        $actions = if ($found.Contains('actions')) { @($found['actions']) } else { @() }
        $expect = ''
        if ($VerdictPath -and (Test-Path -LiteralPath $VerdictPath)) {
            $v = Get-Content -LiteralPath $VerdictPath -Raw | ConvertFrom-Json -AsHashtable
            $expect = 'OverallVerdict {0}. Accuracy {1}. Completeness {2}.' -f $v['OverallVerdict'], $v['accuracy'], $v['completeness']
        }
        [pscustomobject]@{
            exitCode              = $exit
            found                 = $true
            sessionId             = $sessionId
            requestId             = $requestId
            status                = [string]$found['status']
            queryTitle            = [string]$found['queryTitle']
            dialogItems           = $dialog.Count
            actions               = $actions.Count
            designDecisionActions = @($actions | Where-Object { [string]$_['type'] -eq 'design_decision' }).Count
            proseParts            = ([regex]::Matches($joined, 'VERDICT PROSE part')).Count
            jsonParts             = ([regex]::Matches($joined, 'VERDICT JSON part')).Count
            itemLines             = @($texts | Where-Object { $_ -match '^S[1-4]-\d\d \[' }).Count
            findingObjects        = @($texts | Where-Object { $_ -match '^\{"id":"(F|I)-R6-' }).Count
            responseHasVerdict    = if ($expect) { ([string]$found['response']).Contains($expect) } else { $false }
            outPath               = $outPath
            readAt                = (Get-Date -Format s)
        } | ConvertTo-Json -Compress
    }
}

