#Requires -Version 7.0
[CmdletBinding()]
param(
    [ValidateSet('WorkDiff', 'Hash', 'LsRemote', 'BlobHash')]
    [Parameter(Mandatory)][string]$Mode,
    [string[]]$Paths = @(),
    [string]$Revision = '3fb4a49a28ce5281ab91fa88c4d488458762ea27'
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$repo = '[HOME]/github/WordGame/.mcpServer/wordpairs'
Set-Location -LiteralPath $repo
$expanded = @($Paths | ForEach-Object { $_ -split ',' } | Where-Object { $_ })
switch ($Mode) {
    'WorkDiff' { foreach ($p in $expanded) { & git diff HEAD -- $p } }
    'Hash' {
        foreach ($p in $expanded) {
            $full = if ([IO.Path]::IsPathRooted($p)) { $p } else { Join-Path $repo $p }
            if (Test-Path -LiteralPath $full) {
                $item = Get-Item -LiteralPath $full
                '{0} {1} bytes={2} mtime={3}' -f (Get-FileHash -LiteralPath $full -Algorithm SHA256).Hash, $p, $item.Length, $item.LastWriteTime.ToString('s')
            } else { 'MISSING ' + $p }
        }
    }
    'BlobHash' {
        foreach ($p in $expanded) {
            $tmp = [IO.Path]::GetTempFileName()
            try {
                $psi = [Diagnostics.ProcessStartInfo]::new('git')
                $psi.ArgumentList.Add('show')
                $psi.ArgumentList.Add($Revision + ':' + $p)
                $psi.WorkingDirectory = $repo
                $psi.RedirectStandardOutput = $true
                $proc = [Diagnostics.Process]::Start($psi)
                $fs = [IO.File]::Create($tmp)
                $proc.StandardOutput.BaseStream.CopyTo($fs)
                $fs.Close()
                $proc.WaitForExit()
                '{0} {1}:{2} exit={3}' -f (Get-FileHash -LiteralPath $tmp -Algorithm SHA256).Hash, $Revision.Substring(0, 7), $p, $proc.ExitCode
            } finally { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
