#Requires -Version 7.0
[CmdletBinding()]
param(
    [string]$ZipPath = '[HOME]/github/WordGame/.mcpServer/wordpairs/docs/requirements/requirements-wiki-documents.zip'
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

Add-Type -AssemblyName System.IO.Compression
$needles = [ordered]@{
    'INVITE-COPY-03 text' = 'if creation fails or returns no link, no new link is shown or copied'
    'INVITE-COPY-01 text' = 'when they choose Copy Invitation Link and link creation and clipboard access succeed'
    'TR-23-C02 text'      = 'it proposes later core extensions in order'
    'TEST-029 display ticks' = 'cooldown across display ticks'
    'failure analysis ref' = 'reaction-failure-analysis.md'
}
$stream = [IO.File]::OpenRead($ZipPath)
try {
    $zip = [IO.Compression.ZipArchive]::new($stream, [IO.Compression.ZipArchiveMode]::Read)
    'ENTRIES=' + $zip.Entries.Count
    foreach ($key in $needles.Keys) {
        $hits = [System.Collections.Generic.List[string]]::new()
        foreach ($entry in $zip.Entries) {
            if (-not $entry.FullName.EndsWith('.md')) { continue }
            $reader = [IO.StreamReader]::new($entry.Open())
            try { if ($reader.ReadToEnd().Contains($needles[$key])) { $hits.Add($entry.FullName) } } finally { $reader.Dispose() }
        }
        '{0}: {1} -> {2}' -f $key, $hits.Count, (@($hits | Select-Object -First 6) -join '; ')
    }
} finally { $stream.Dispose() }
'AT=' + (Get-Date -Format s)

