)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$ev = 'docs/evidence/hosting/guest-admin-recovery'
$tools = 'docs/receipts/hv/claude-opus-round6-tools'
function New-Item6 {
    param([string]$Id, [string]$Surface, [string]$Status, [string]$Claim, [string[]]$Anchors, [string]$Finding = '')
    [ordered]@{ id = $Id; surface = $Surface; status = $Status; claim = $Claim; anchors = $Anchors; finding = $Finding }
}
function New-Finding6 {
    param([string]$Id, [string]$Severity, [string]$Class, [string]$Title, [string]$Detail, [string[]]$Requirements = @(), [string]$ProposedAC = '', [string[]]$ProposedTests = @())
    [ordered]@{ id = $Id; severity = $Severity; class = $Class; title = $Title; detail = $Detail; requirements = $Requirements; proposedAC = $ProposedAC; proposedTests = $ProposedTests; operatorDecision = '' }
}

